from math import isqrt


def _build_prime_table(limit: int):
    is_prime = [True] * (limit + 1)
    if limit >= 0:
        is_prime[0] = False
    if limit >= 1:
        is_prime[1] = False
    for value in range(2, isqrt(limit) + 1):
        if not is_prime[value]:
            continue
        start = value * value
        is_prime[start : limit + 1 : value] = [False] * (((limit - start) // value) + 1)
    return is_prime


def solve() -> None:
    _ = int(input().strip())
    values = list(map(int, input().split()))
    limit = isqrt(max(values, default=0))
    is_prime = _build_prime_table(limit)
    answers = []
    for value in values:
        root = isqrt(value)
        answers.append("YES" if root * root == value and is_prime[root] else "NO")
    print("\n".join(answers))


if __name__ == "__main__":
    solve()

