from math import isqrt


def solve() -> None:
    _ = int(input().strip())
    values = list(map(int, input().split()))
    answers: list[str] = []
    for value in values:
        divisors = 0
        for candidate in range(1, isqrt(value) + 1):
            if value % candidate != 0:
                continue
            divisors += 1 if candidate * candidate == value else 2
            if divisors > 3:
                break
        answers.append("YES" if divisors == 3 else "NO")
    print("\n".join(answers))


if __name__ == "__main__":
    solve()
